'use strict';
window.RepoAdminHelp=(()=>{
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const repo='https://github.com/sparx1981/RepoShelf';
function code(id,text){return `<div class="help-code"><button type="button" class="copy-code" data-copy-code="${id}">Copy</button><pre id="${id}"><code>${escape(text)}</code></pre></div>`}
function flag(ok){return `<span class="setup-flag ${ok?'ready':'missing'}">${ok?'Configured':'Needs setup'}</span>`}
function render(setup){const origin=setup.origin,remote=`[mcp_servers.reposhelf]\nurl = "${origin}/api/mcp"\nbearer_token_env_var = "REPOSHELF_API_KEY"`,desktop=JSON.stringify({mcpServers:{reposhelf:{command:'node',args:['/absolute/path/RepoShelf/scripts/mcp-server.mjs','--remote',origin],env:{REPOSHELF_API_KEY:'YOUR_PRIVATE_API_KEY'}}}},null,2);return `<section class="analytics-box help-status"><h3>Connection status</h3><div class="setup-status"><span>Supabase account configuration</span>${flag(setup.supabase.configured)}<span>Analytics ingestion key</span>${flag(setup.supabase.analyticsKeyConfigured)}<span>MCP / agent API key</span>${flag(setup.agentKeyConfigured)}</div><p class="analytics-caption">These flags confirm environment settings are present. They do not test credentials, OAuth or migrations. Secret values are never displayed.</p></section><div class="help-layout"><section class="analytics-box help-card"><p class="eyebrow">CODING AGENTS</p><h3>Connect Codex to RepoShelf</h3><ol><li>Add <code>REPOSHELF_API_KEY</code> in Vercel’s Production environment and redeploy. Use at least 32 random characters.</li><li>Set the same key securely in the environment running Codex.</li><li>Add this to your Codex MCP configuration:</li></ol>${code('codex-mcp-config',remote)}<p class="small">Ask your agent to search RepoShelf before building, inspect project context, then read saved READMEs and licences. All tools are read-only.</p><p><a href="${repo}/blob/main/docs/AGENT_API.md" target="_blank" rel="noopener">Full API and MCP guide ↗</a></p></section><section class="analytics-box help-card"><p class="eyebrow">CODING AGENTS</p><h3>Connect Claude Desktop</h3><ol><li>Clone RepoShelf and run <code>npm install</code>. Node.js 20 or later is required.</li><li>Use the local stdio bridge below to read the current hosted catalog.</li><li>Replace the example path and key in your private Claude Desktop configuration, then restart the client.</li></ol>${code('claude-mcp-config',desktop)}<p class="small">The key above is a placeholder. Keep your actual key private and out of Git, URLs and command-line arguments. A client secret manager/environment configuration is preferable when available.</p><details><summary>Use a local checkout without a hosted key</summary><p>Remove <code>--remote</code>, the hosted URL and the <code>env</code> entry. The server then reads the saved catalog in your checkout. Use <code>git pull</code> to keep it current.</p></details><p class="small">The remote MCP endpoint uses a Bearer header. OAuth-only connectors need the stdio bridge or a client that supports custom authentication.</p></section><section class="analytics-box help-card"><p class="eyebrow">ACCOUNTS AND STORAGE</p><h3>Configure Supabase</h3><ol><li>Connect a Supabase project to RepoShelf in Vercel’s Storage settings.</li><li>Apply the database migrations in order. Existing projects should apply only migrations they have not run yet.</li><li>Set the server variables below in Vercel’s Production environment, then redeploy.</li></ol><div class="help-table-wrap"><table class="analytics-table"><thead><tr><th>Setting</th><th>Purpose</th></tr></thead><tbody><tr><td><code>SUPABASE_URL</code></td><td>Project URL</td></tr><tr><td><code>SUPABASE_ANON_KEY</code></td><td>Publishable or legacy anon key</td></tr><tr><td><code>SUPABASE_SERVICE_ROLE_KEY</code></td><td>Private analytics ingestion</td></tr><tr><td><code>REPOSHELF_PUBLIC_URL</code></td><td>${escape(origin)}</td></tr></tbody></table></div><p class="small">Marketplace aliases are supported. Database and OAuth secrets stay on the server.</p><ul><li><a href="${repo}/blob/main/supabase/migrations/202610030001_accounts_editorial_analytics.sql" target="_blank" rel="noopener">1. Accounts, collections, editorial and analytics migration ↗</a></li><li><a href="${repo}/blob/main/supabase/migrations/202610030002_admin_user_management.sql" target="_blank" rel="noopener">2. Administrator user-management migration ↗</a></li></ul><p><a href="https://supabase.com/dashboard" target="_blank" rel="noopener">Open Supabase dashboard ↗</a></p></section><section class="analytics-box help-card"><p class="eyebrow">GITHUB SIGN-IN</p><h3>Configure OAuth and redirects</h3><ol><li>Create a GitHub OAuth App. Its homepage is <code>${escape(origin)}</code>, and its callback is <code>https://YOUR_PROJECT.supabase.co/auth/v1/callback</code>.</li><li>Enable GitHub in Supabase Authentication → Providers and enter the OAuth app’s client ID and secret.</li><li>Set Supabase’s Site URL to <code>${escape(origin)}</code> and allow this redirect:</li></ol>${code('oauth-redirect-url',origin+'/api/auth?action=callback')}<p class="small">Custom and preview domains need their own explicit settings. Repository write access is not needed for sign-in or browsing; fork links open GitHub.</p><p><a href="${repo}/blob/main/docs/ACCOUNTS_AND_ADMIN.md" target="_blank" rel="noopener">Complete accounts and administration guide ↗</a></p></section><section class="analytics-box help-card"><p class="eyebrow">ADMINISTRATION</p><h3>Give someone administrator access</h3><ol><li>Ask the person to sign in to RepoShelf with GitHub once.</li><li>Open <button class="help-inline-button" data-admin-tab="users">Users & roles</button> and search their GitHub username, GitHub ID or account UUID.</li><li>Check the identity, select <strong>Grant admin</strong>, and confirm. The person can reload to see the admin menu.</li></ol><p class="small">Administrators can manage category rows, read analytics and grant roles. User-controlled profile metadata never grants access. Your own role and the last administrator are protected, and changes are recorded.</p><details><summary>Bootstrap the first administrator</summary><p>After sign-in, verify your user in Supabase Authentication → Users. Run this in its SQL editor, replacing the placeholder with that verified user’s UUID:</p>${code('bootstrap-admin-sql',"insert into public.reposhelf_admins(user_id)\nvalues ('YOUR-VERIFIED-USER-UUID')\non conflict do nothing;")}<p>The first administrator must be established through Supabase. Existing admins can then manage access in RepoShelf.</p></details></section><section class="analytics-box help-card"><p class="eyebrow">TROUBLESHOOTING</p><h3>When something needs attention</h3><ul><li><strong>MCP returns 503:</strong> check the API key is configured and redeploy.</li><li><strong>MCP returns 401:</strong> the client and server keys do not match.</li><li><strong>Sign-in fails:</strong> check both GitHub’s Supabase callback and Supabase’s RepoShelf redirect allowlist.</li><li><strong>User management needs a database update:</strong> apply migration 2 above.</li><li><strong>A user is missing:</strong> they must complete GitHub sign-in once. Clear the search or check their account ID.</li><li><strong>Analytics are empty:</strong> check the ingestion key. Activity starts after activation; admin activity and browser privacy opt-outs are excluded.</li></ul><p class="small">Catalog discovery continues every six hours. Missing README and screenshot coverage improves in scheduled batches. Fork clicks do not prove that a fork succeeded.</p></section></div>`}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-copy-code]');if(!button)return;const text=document.getElementById(button.dataset.copyCode)?.textContent;if(!text)return;try{await navigator.clipboard.writeText(text);button.textContent='Copied';setTimeout(()=>button.textContent='Copy',1500)}catch{button.textContent='Select text to copy'}});
return {render};
})();
